import{z as l,x as p,o,c as B,q as t,j as r,D as e,d as s,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"PoW 与区块链共识直觉","description":"","frontmatter":{"title":"PoW 与区块链共识直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pow-blockchain-consensus.md","filePath":"cs/pow-blockchain-consensus.md","lastUpdated":1791413859000}'),A={name:"cs/pow-blockchain-consensus.md"};function c(d,a,P,h,_,m){const E=p("Mermaid");return o(),B("div",null,[a[2]||(a[2]=t('<h1 id="pow-与区块链共识直觉" tabindex="-1">PoW 与区块链共识直觉 <a class="header-anchor" href="#pow-与区块链共识直觉" aria-label="Permalink to &quot;PoW 与区块链共识直觉&quot;">​</a></h1><div class="epigraph"><p>开放成员里没有 $n$ 与 $f$ 的名册。工作量证明让出块权变贵，最长链是一种概率最终的全序，不是 Paxos 的多数派选定。</p><footer>—— 据 Nakamoto, Bitcoin: A Peer-to-Peer Electronic Cash System, 2008；Lamport 拜占庭将军与 Castro PBFT 对照整理</footer></div><p>上一课<a href="/cs/etcd-chubby">etcd/Chubby</a>假定已知副本集。缺口是<strong>许可名单不存在</strong>时如何对日志达成序。本课只给计算机课需要的直觉：PoW 换了故障与同步假设，不把加密货币、交易所或限价簿写进来。共识单元在此封口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PBFT 要 \\(n=3f+1\\) 且身份已知。开放网络身份可伪造（Sybil）。<span class="marginnote">Sybil 攻击直译是「一人伪装千面」：在免费注册的开放网络里，坏人选一万个人设账号冒充一万台诚实机器，任何按「人头数」投票的规则立刻被买通。PoW 的对策是不数人头数算力——算力造不了假，买一万张身份证买不来一万倍的电费。</span>Nakamoto：出块须找哈希低于目标，期望耗时由难度调节。后继块指针形成树，客户端跟<strong>累计工作最多</strong>的链。重组：更长（更重）的链让浅块失去最终性——最终性是概率随深度指数降，不是多数派证书。</p><p>缺口：这不是<a href="/cs/linearizability">线性一致</a>寄存器。读「最新块」可在分叉上。确认数是应用选的深度，不是 Herlihy–Wing 的线性化点。</p><p><span class="marginnote">2008 白皮书不是同行评审 TODS，但是 PoW 链的源头文献。Dwork–Naor 的定价邮件是 PoW 更早思想，点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表（直觉，不证经济）：</p><p>| | Raft/PBFT | PoW 链 | | 成员 | 已知 | 开放 | | 安全阈值 | \\(f\\) 相对 \\(n\\) | 算力比例 | | 最终性 | 提交后确定 | 深度概率 | | 同步 | 部分同步活性 | 出块间隔相对传播延迟 |</p>',10)),(o(),r(i,null,{default:e(()=>[n(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20POW%5B%22%E8%A7%A3%E5%93%88%E5%B8%8C%22%5D%20--%3E%20BLK%5B%22%E5%87%BA%E5%9D%97%22%5D%0A%20%20BLK%20--%3E%20CHAIN%5B%22%E6%8C%87%E9%92%88%E6%88%90%E9%93%BE%22%5D%0A%20%20FORK%5B%22%E5%88%86%E5%8F%89%22%5D%20--%3E%20W%5B%22%E6%9B%B4%E9%87%8D%E8%80%85%E8%B5%A2%22%5D%0A%20%20W%20--%3E%20PROB%5B%22%E6%B5%85%E5%9D%97%E5%8F%AF%E8%A2%AB%E9%87%8D%E7%BB%84%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：「找哈希低于目标」像全世界的矿工同时在摇亿面骰子，谁先摇出符合条件的一面谁记账。目标值就是中奖线——把线调低，每次摇中的概率变小，全网平均要摇更多次才出一块；摇骰子本身无法作弊加速，只能多买骰子（算力）。</span></p><p>不要把挖矿当<a href="/cs/failure-detectors">故障检测器</a>。也不要把难度当 NTP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>传播延迟若接近出块间隔，分叉率上升，安全性依赖「诚实算力多数」加足够慢的出块。这是同步味道的假设，与 FLP 异步确定共识不是同一格子。自私挖矿等攻击说明激励与算法缠在一起——本课点名，不写博弈全文。</p><p>许可链用 PBFT 族更常见：成员又回来了。PoW 的课程序列价值是：共识不一定长成 prepare/accept。数据中心有名册时，用 Raft 比用 PoW 更符合故障模型。</p><p>本课不写智能合约、不写 Transformer、不写 LOB。</p><p>难度不是拍脑袋定的，而是一条反馈回路——它解释了为什么全网算力涨几十倍，出块间隔仍大致不变：</p>',7)),(o(),r(i,null,{default:e(()=>[n(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%A8%E7%BD%91%E7%AE%97%E5%8A%9B%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20B%5B%22%E5%87%BA%E5%9D%97%E5%BF%AB%E4%BA%8E%E7%9B%AE%E6%A0%87%E9%97%B4%E9%9A%94%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%91%A8%E6%9C%9F%E6%9C%AB%E7%BB%9F%E8%AE%A1%E5%AE%9E%E9%99%85%E5%87%BA%E5%9D%97%E9%80%9F%E5%BA%A6%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%B0%83%E4%BD%8E%E7%9B%AE%E6%A0%87%E5%80%BC%EF%BC%8C%E5%93%88%E5%B8%8C%E6%9B%B4%E9%9A%BE%E8%BE%BE%E6%A0%87%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%87%BA%E5%9D%97%E9%97%B4%E9%9A%94%E5%9B%9E%E5%88%B0%E7%9B%AE%E6%A0%87%22%5D%0A%20%20E%20--%3E%20A%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">数字实例：确认数的意义可以算出来。若攻击者占全网算力的少数（如一成），他要在背后追上主链 \\(k\\) 个块，概率随 \\(k\\) 指数衰减——浅处 \\(1\\) 个确认的交易被翻盘不算稀奇，\\(6\\) 个确认后对小算力攻击者已接近不可能。这就是交易所「等六个确认」的来历：不是协议保证，而是把概率压到可忽略的应用选择。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析奖励函数，不引入权益证明细节。不给投资建议。后课系统模式从 RPC 开始，默认仍在数据中心崩溃模型；只有需要开放成员全序时才回想到 PoW 的概率最终。</p><p>有名册，用法定人数。无名册，用昂贵的出块权加概率深度。不要把后者的话术套到 etcd。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PoW 抗 Sybil：出块耗能，最长（最重）链排序。</li><li>最终性是深度上的概率，不是多数派证书。</li><li>已知成员的数据中心协调仍用 Raft/Paxos/PBFT。</li><li>出处：Nakamoto, 2008；对照 Lamport BGP、Castro PBFT。</li></ul>',6))])}const u=l(A,[["render",c]]);export{D as __pageData,u as default};
